import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

public final class PropertyMerger {
    private PropertyMerger() {
    }

    @Nullable
    public static <T> T meldProperty(@Nullable T a, @Nullable T b) {
        if (a == null) {
            return b;
        }
        if (b == null) {
            return a;
        }
        return mergeProperty(a, b);
    }

    private static <T> T mergeProperty(T a, T b) {
        // Generic values have no universal merge operation.
        // The default merge keeps the first non-null value.
        return a;
    }

    @Retention(RetentionPolicy.CLASS)
    @Target({
        ElementType.METHOD,
        ElementType.PARAMETER,
        ElementType.FIELD,
        ElementType.TYPE_USE
    })
    public @interface Nullable {
    }
}

