public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    Score_ scoreDifference = score.subtract(other.score);
    java.util.Map<ConstraintRef, ConstraintAnalysis<Score_>> differenceMap =
            new java.util.HashMap<>();

    java.util.Set<ConstraintRef> constraintRefs =
            new java.util.HashSet<>(getConstraintAnalysisMap().keySet());
    constraintRefs.addAll(other.getConstraintAnalysisMap().keySet());

    for (ConstraintRef constraintRef : constraintRefs) {
        ConstraintAnalysis<Score_> thisAnalysis =
                getConstraintAnalysisMap().get(constraintRef);
        ConstraintAnalysis<Score_> otherAnalysis =
                other.getConstraintAnalysisMap().get(constraintRef);

        Score_ zero = score.zero();
        if (thisAnalysis == null) {
            thisAnalysis = new ConstraintAnalysis<>(
                    constraintRef,
                    zero,
                    zero,
                    java.util.Collections.emptyList());
        }
        if (otherAnalysis == null) {
            otherAnalysis = new ConstraintAnalysis<>(
                    constraintRef,
                    zero,
                    zero,
                    java.util.Collections.emptyList());
        }

        ConstraintAnalysis<Score_> constraintDifference =
                thisAnalysis.diff(otherAnalysis);

        boolean hasWeightDifference =
                !constraintDifference.getWeight().equals(zero);
        boolean hasScoreDifference =
                !constraintDifference.getScore().equals(zero);
        boolean hasMatchDifference =
                !constraintDifference.getMatchAnalysisList().isEmpty();

        if (hasWeightDifference || hasScoreDifference || hasMatchDifference) {
            differenceMap.put(constraintRef, constraintDifference);
        }
    }

    return new ScoreAnalysis<>(scoreDifference, differenceMap);
}

