public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    java.util.Map<ConstraintRef, ConstraintAnalysis<Score_>> result =
            new java.util.LinkedHashMap<>();

    java.util.Set<ConstraintRef> constraintRefs =
            new java.util.LinkedHashSet<>(getConstraintAnalysisMap().keySet());
    constraintRefs.addAll(other.getConstraintAnalysisMap().keySet());

    for (ConstraintRef constraintRef : constraintRefs) {
        ConstraintAnalysis<Score_> currentAnalysis =
                getConstraintAnalysisMap().get(constraintRef);
        ConstraintAnalysis<Score_> otherAnalysis =
                other.getConstraintAnalysisMap().get(constraintRef);

        boolean currentHasMatches = currentAnalysis != null
                && currentAnalysis.getMatchAnalysisList() != null
                && !currentAnalysis.getMatchAnalysisList().isEmpty();
        boolean otherHasMatches = otherAnalysis != null
                && otherAnalysis.getMatchAnalysisList() != null
                && !otherAnalysis.getMatchAnalysisList().isEmpty();

        if (currentHasMatches != otherHasMatches) {
            throw new IllegalArgumentException(
                    "Cannot diff score analyses with incompatible match data for constraint "
                            + constraintRef + ".");
        }

        ConstraintAnalysis<Score_> constraintDiff;
        if (currentAnalysis == null) {
            Score_ zeroWeight = otherAnalysis.getWeight().zero();
            Score_ zeroScore = otherAnalysis.getScore().zero();
            ConstraintAnalysis<Score_> zeroAnalysis = new ConstraintAnalysis<>(
                    constraintRef,
                    zeroWeight,
                    zeroScore,
                    java.util.Collections.emptyList());
            constraintDiff = zeroAnalysis.diff(otherAnalysis);
        } else if (otherAnalysis == null) {
            Score_ zeroWeight = currentAnalysis.getWeight().zero();
            Score_ zeroScore = currentAnalysis.getScore().zero();
            ConstraintAnalysis<Score_> zeroAnalysis = new ConstraintAnalysis<>(
                    constraintRef,
                    zeroWeight,
                    zeroScore,
                    java.util.Collections.emptyList());
            constraintDiff = currentAnalysis.diff(zeroAnalysis);
        } else {
            constraintDiff = currentAnalysis.diff(otherAnalysis);
        }

        boolean hasWeightDifference = !constraintDiff.getWeight().isZero();
        boolean hasScoreDifference = !constraintDiff.getScore().isZero();
        boolean hasMatchDifference = constraintDiff.getMatchAnalysisList() != null
                && !constraintDiff.getMatchAnalysisList().isEmpty();

        if (hasWeightDifference || hasScoreDifference || hasMatchDifference) {
            result.put(constraintRef, constraintDiff);
        }
    }

    return new ScoreAnalysis<>(getScore().subtract(other.getScore()), result);
}

