public @NonNull ScoreAnalysis<Score_> diff(@NonNull ScoreAnalysis<Score_> other) {
    java.util.Map<ConstraintRef, ConstraintAnalysis<Score_>> thisConstraintAnalysisMap =
            getConstraintAnalysisMap();
    java.util.Map<ConstraintRef, ConstraintAnalysis<Score_>> otherConstraintAnalysisMap =
            other.getConstraintAnalysisMap();

    boolean thisHasMatchData = thisConstraintAnalysisMap.values().stream()
            .anyMatch(constraintAnalysis -> !constraintAnalysis.getMatchAnalysisList().isEmpty());
    boolean otherHasMatchData = otherConstraintAnalysisMap.values().stream()
            .anyMatch(constraintAnalysis -> !constraintAnalysis.getMatchAnalysisList().isEmpty());

    if (thisHasMatchData != otherHasMatchData) {
        throw new IllegalArgumentException(
                "Both ScoreAnalysis instances must either contain match data or not contain match data.");
    }

    java.util.Set<ConstraintRef> constraintRefs = new java.util.LinkedHashSet<>();
    constraintRefs.addAll(thisConstraintAnalysisMap.keySet());
    constraintRefs.addAll(otherConstraintAnalysisMap.keySet());

    java.util.Map<ConstraintRef, ConstraintAnalysis<Score_>> differenceMap =
            new java.util.LinkedHashMap<>();

    for (ConstraintRef constraintRef : constraintRefs) {
        ConstraintAnalysis<Score_> thisConstraintAnalysis =
                thisConstraintAnalysisMap.get(constraintRef);
        ConstraintAnalysis<Score_> otherConstraintAnalysis =
                otherConstraintAnalysisMap.get(constraintRef);

        boolean thisHasConstraintMatchData = thisConstraintAnalysis != null
                && !thisConstraintAnalysis.getMatchAnalysisList().isEmpty();
        boolean otherHasConstraintMatchData = otherConstraintAnalysis != null
                && !otherConstraintAnalysis.getMatchAnalysisList().isEmpty();

        if (thisHasConstraintMatchData != otherHasConstraintMatchData) {
            throw new IllegalArgumentException(
                    "Both ScoreAnalysis instances must contain matching match data for constraint "
                            + constraintRef + ".");
        }

        ConstraintAnalysis<Score_> constraintDifference;
        if (thisConstraintAnalysis != null && otherConstraintAnalysis != null) {
            constraintDifference = thisConstraintAnalysis.diff(otherConstraintAnalysis);
        } else if (thisConstraintAnalysis != null) {
            Score_ zero = thisConstraintAnalysis.getScore().zero();
            constraintDifference = ConstraintAnalysis.of(
                    constraintRef,
                    thisConstraintAnalysis.getWeight().subtract(zero),
                    thisConstraintAnalysis.getScore().subtract(zero),
                    java.util.Collections.emptyList());
