        boolean hasScoreDifference = !constraintDifference.getScore().isZero();
        boolean hasMatchDifference = !constraintDifference.getMatchAnalysisList().isEmpty();

        if (hasWeightDifference || hasScoreDifference || hasMatchDifference) {
            differenceMap.put(constraintRef, constraintDifference);
        }
    }

    Score_ scoreDifference = getScore().subtract(other.getScore());
    return new ScoreAnalysis<>(scoreDifference, differenceMap, isSolutionInitialized());
