List<Document> get() {
	List<Document> documents = new ArrayList<>();

	List<Paragraph> paragraphs = this.paragraphTextExtractor.getParagraphs(this.config);
	if (CollectionUtils.isEmpty(paragraphs)) {
		return documents;
	}

	for (int i = 0; i < paragraphs.size(); i++) {
		Paragraph current = paragraphs.get(i);
		Paragraph next = (i + 1 < paragraphs.size()) ? paragraphs.get(i + 1) : current;

		String text = this.paragraphTextExtractor.getText(current, next);
		if (!StringUtils.hasText(text)) {
			continue;
		}

		Document document = new Document(text);
		document.getMetadata().put(METADATA_START_PAGE, current.getPageNumber());
		document.getMetadata().put(METADATA_END_PAGE, next.getPageNumber());
		document.getMetadata().put(METADATA_TITLE, current.getTitle());
		document.getMetadata().put(METADATA_LEVEL, current.getLevel());
		document.getMetadata().put(METADATA_FILE_NAME, this.resourceFileName);

		documents.add(document);
	}

	return documents;
}

