import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class ParagraphDocumentProcessor {
    private final List<String> paragraphs;

    public ParagraphDocumentProcessor(List<String> paragraphs) {
        this.paragraphs = paragraphs;
    }

    public List<Document> get() {
        System.out.println("Start processing paragraphs from PDF");

        List<Document> documents = new ArrayList<>();

        if (paragraphs == null || paragraphs.isEmpty()) {
            System.out.println("End processing paragraphs from PDF");
            return Collections.emptyList();
        }

        for (int i = 0; i < paragraphs.size(); i++) {
            String currentParagraph = paragraphs.get(i);
            String nextParagraph = i + 1 < paragraphs.size()
                    ? paragraphs.get(i + 1)
                    : currentParagraph;

            Document document = createDocument(currentParagraph, nextParagraph);

            if (document != null
                    && document.getText() != null
                    && !document.getText().trim().isEmpty()) {
                documents.add(document);
            }
        }

        System.out.println("End processing paragraphs from PDF");
        return documents;
    }

    private Document createDocument(String firstParagraph, String secondParagraph) {
        String first = firstParagraph == null ? "" : firstParagraph;
        String second = secondParagraph == null ? "" : secondParagraph;

        return new Document(first + System.lineSeparator() + second);
    }
}

class Document {
    private final String text;

    public Document(String text) {
        this.text = text;
    }

    public String getText() {
        return text;
    }
}

