import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public final class InlineFeatureWriter {

    private final Map<FeatureId, Feature> featureMap;
    private final List<Feature> inlineFeatures;
    private final FileChannel output;

    public InlineFeatureWriter(
            Map<FeatureId, Feature> featureMap,
            List<Feature> inlineFeatures,
            FileChannel output) {

        this.featureMap = Objects.requireNonNull(featureMap, "featureMap");
        this.inlineFeatures = Objects.requireNonNull(inlineFeatures, "inlineFeatures");
        this.output = Objects.requireNonNull(output, "output");
    }

    /**
     * Writes the inline feature states for one ordinal.
     *
     * Each ordinal occupies the same number of bytes. Missing states are
     * skipped so that subsequent feature data remains properly aligned.
     */
    public void writeInline(
            int ordinal,
            Map<FeatureId, Feature.State> stateMap) throws IOException {

        if (ordinal < 0) {
            throw new IllegalArgumentException("ordinal must not be negative");
        }
        Objects.requireNonNull(stateMap, "stateMap");

        // Validate the complete state map before changing the output position
        // or writing any data.
        for (FeatureId featureId : stateMap.keySet()) {
            if (!featureMap.containsKey(featureId)) {
                throw new IllegalArgumentException(
                        "Missing feature in featureMap: " + featureId);
            }
        }

        long inlineSize = 0L;
        for (Feature feature : inlineFeatures) {
            inlineSize = Math.addExact(inlineSize, feature.size());
        }

        long offset = Math.multiplyExact(ordinal, inlineSize);
        output.position(offset);

        for (Feature feature : inlineFeatures) {
            Feature.State state = stateMap.get(feature.id());

            if (state != null) {
                feature.writeInline(output, state);
            } else {
                skip(feature.size());
            }
        }
    }

    private void skip(long byteCount) throws IOException {
        if (byteCount < 0) {
            throw new IllegalArgumentException("Feature size must not be negative");
        }

        output.position(Math.addExact(output.position(), byteCount));
    }

    public interface Feature {
        FeatureId id();

        /**
         * Number of bytes reserved by this feature in each ordinal.
         */
        long size();

        void writeInline(FileChannel output, State state) throws IOException;

        interface State {
        }
    }

    public static final class FeatureId {
        private final String value;

        public FeatureId(String value) {
            this.value = Objects.requireNonNull(value, "value");
        }

        public String value() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof FeatureId)) {
                return false;
            }
            FeatureId that = (FeatureId) other;
            return value.equals(that.value);
        }

        @Override
        public int hashCode() {
            return value.hashCode();
        }

        @Override
        public String toString() {
            return value;
        }
    }

    /**
     * Optional helper for features that write fixed-width byte data.
     */
    public static void writeBytes(
            FileChannel output,
            byte[] bytes,
            long reservedSize) throws IOException {

        Objects.requireNonNull(bytes, "bytes");

        if (bytes.length > reservedSize) {
            throw new IllegalArgumentException(
                    "Feature data exceeds its reserved size");
        }

        output.write(ByteBuffer.wrap(bytes));

        long padding = reservedSize - bytes.length;
        if (padding > 0) {
            output.position(Math.addExact(output.position(), padding));
        }
    }
}

