import java.io.IOException;
import java.io.RandomAccessFile;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Objects;

public final class InlineFeatureWriter {
    private final RandomAccessFile output;
    private final List<Feature> inlineFeatures;
    private final Map<FeatureId, Feature> featureMap;
    private final long firstOrdinalOffset;
    private final long inlineRecordSize;

    public InlineFeatureWriter(
            RandomAccessFile output,
            List<Feature> inlineFeatures,
            Map<FeatureId, Feature> featureMap,
            long firstOrdinalOffset) {

        this.output = Objects.requireNonNull(output, "output");
        this.inlineFeatures = List.copyOf(
                Objects.requireNonNull(inlineFeatures, "inlineFeatures"));
        this.featureMap = Collections.unmodifiableMap(
                Objects.requireNonNull(featureMap, "featureMap"));
        this.firstOrdinalOffset = firstOrdinalOffset;

        long recordSize = 0;
        for (Feature feature : this.inlineFeatures) {
            Objects.requireNonNull(feature, "inlineFeatures contains null");
            if (feature.inlineSize() < 0) {
                throw new IllegalArgumentException(
                        "Feature size cannot be negative: " + feature.id());
            }
            recordSize = Math.addExact(recordSize, feature.inlineSize());
        }
        this.inlineRecordSize = recordSize;
    }

    /**
     * Writes the inline state for the given ordinal.
     *
     * @param ordinal ordinal of the record to write
     * @param stateMap states indexed by feature ID
     * @throws IOException if the output cannot be positioned or written
     * @throws IllegalArgumentException if the ordinal is invalid or the state
     *                                  map contains an unknown feature
     */
    public void writeInline(
            int ordinal,
            Map<FeatureId, Feature.State> stateMap) throws IOException {

        Objects.requireNonNull(stateMap, "stateMap");

        /*
         * Validate the complete state map before seeking or writing anything.
         */
        for (FeatureId featureId : stateMap.keySet()) {
            if (!featureMap.containsKey(featureId)) {
                throw new IllegalArgumentException(
                        "Missing feature in featureMap: " + featureId);
            }
        }

        output.seek(featureOffsetForOrdinal(ordinal));

        for (Feature feature : inlineFeatures) {
            Feature.State state = stateMap.get(feature.id());

            if (state != null) {
                feature.writeInline(output, state);
            } else {
                /*
                 * Advance over the feature's reserved space so that all
                 * following features remain at their predefined offsets.
                 */
                long nextPosition = Math.addExact(
                        output.getFilePointer(), feature.inlineSize());
                output.seek(nextPosition);
            }
        }
    }

    /**
     * Returns the precomputed output position for an ordinal.
     */
    private long featureOffsetForOrdinal(int ordinal) {
        if (ordinal < 0) {
            throw new IllegalArgumentException(
                    "Ordinal must be non-negative: " + ordinal);
        }

        try {
            return Math.addExact(
                    firstOrdinalOffset,
                    Math.multiplyExact((long) ordinal, inlineRecordSize));
        } catch (ArithmeticException ex) {
            throw new IllegalArgumentException(
                    "Ordinal produces an invalid feature offset: " + ordinal,
                    ex);
        }
    }

    public static final class FeatureId {
        private final String value;

        public FeatureId(String value) {
            this.value = Objects.requireNonNull(value, "value");
        }

        public String value() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof FeatureId)) {
                return false;
            }
            FeatureId that = (FeatureId) other;
            return value.equals(that.value);
        }

        @Override
        public int hashCode() {
            return value.hashCode();
        }

        @Override
        public String toString() {
            return value;
        }
    }

    public interface Feature {
        FeatureId id();

        /**
         * Number of bytes reserved for this feature in every inline record.
         */
        int inlineSize();

        void writeInline(RandomAccessFile output, State state)
                throws IOException;

        interface State {
        }
    }
}

