/**
 * Writes fixed-width inline feature data at precomputed ordinal offsets.
 */
public final class InlineFeatureWriter {

    private final SeekableOutput output;
    private final List<Feature> inlineFeatures;
    private final Map<FeatureId, Feature> featureMap;
    private final long[] ordinalOffsets;

    public InlineFeatureWriter(
            SeekableOutput output,
            List<Feature> inlineFeatures,
            Map<FeatureId, Feature> featureMap,
            long[] ordinalOffsets) {

        this.output = Objects.requireNonNull(output, "output");
        this.inlineFeatures = List.copyOf(
                Objects.requireNonNull(inlineFeatures, "inlineFeatures"));
        this.featureMap = Map.copyOf(
                Objects.requireNonNull(featureMap, "featureMap"));
        this.ordinalOffsets = Objects.requireNonNull(ordinalOffsets, "ordinalOffsets").clone();
    }

    /**
     * Writes the inline feature state for the specified ordinal.
     *
     * <p>The method validates the complete state map before seeking or writing
     * any data. Missing states are represented by reserved feature space and
     * are therefore skipped to preserve alignment.</p>
     */
    public synchronized void writeInline(
            int ordinal,
            Map<FeatureId, Feature.State> stateMap) throws IOException {

        Objects.requireNonNull(stateMap, "stateMap");

        // Validate every supplied feature ID before changing the output position.
        for (FeatureId featureId : stateMap.keySet()) {
            if (!featureMap.containsKey(featureId)) {
                throw new IllegalArgumentException(
                        "Missing feature in featureMap: " + featureId);
            }
        }

        // Seek to the exact precomputed position for this ordinal.
        output.seek(featureOffsetForOrdinal(ordinal));

        for (Feature feature : inlineFeatures) {
            Feature.State state = stateMap.get(feature.id());

            if (state != null) {
                feature.writeInline(output, state);
            } else {
                // Reserve the feature's fixed-width area without writing data.
                output.seek(output.position() + feature.inlineSize());
            }
        }
    }

    private long featureOffsetForOrdinal(int ordinal) {
        if (ordinal < 0 || ordinal >= ordinalOffsets.length) {
            throw new IllegalArgumentException("Invalid ordinal: " + ordinal);
        }
        return ordinalOffsets[ordinal];
    }

    public interface SeekableOutput {
        void seek(long position) throws IOException;

        long position() throws IOException;

        void write(byte[] data) throws IOException;
    }

    public interface Feature {
        FeatureId id();

        int inlineSize();

        void writeInline(SeekableOutput output, State state) throws IOException;

        interface State {
        }
    }

    public static final class FeatureId {
        private final String value;

        public FeatureId(String value) {
            this.value = Objects.requireNonNull(value, "value");
        }

        public String value() {
            return value;
        }

        @Override
        public boolean equals(Object other) {
            if (this == other) {
                return true;
            }
            if (!(other instanceof FeatureId)) {
                return false;
            }
            FeatureId that = (FeatureId) other;
            return value.equals(that.value);
        }

        @Override
        public int hashCode() {
            return value.hashCode();
        }

        @Override
        public String toString() {
            return value;
        }
    }
}

