import ai.timefold.solver.core.api.score.analysis.ConstraintAnalysis;
import ai.timefold.solver.core.api.score.analysis.MatchAnalysis;
import ai.timefold.solver.core.api.score.Score;

public final class ScoreSummarizer {

    private ScoreSummarizer() {
    }

    public static <Score_ extends Score<Score_>> String summarize(
            ConstraintAnalysis<Score_> constraintAnalysis) {
        StringBuilder summary = new StringBuilder();

        summary.append("Constraint: ")
                .append(constraintAnalysis.constraintRef())
                .append(System.lineSeparator());
        summary.append("Score: ")
                .append(constraintAnalysis.score())
                .append(System.lineSeparator());

        var matches = constraintAnalysis.matches();
        int matchCount = constraintAnalysis.matchCount();

        if (matches == null) {
            summary.append("Matches: unavailable");
            if (matchCount >= 0) {
                summary.append(" (").append(matchCount).append(")");
            }
            summary.append(System.lineSeparator());
            return summary.toString();
        }

        summary.append("Matches: ")
                .append(matchCount)
                .append(System.lineSeparator());

        for (int i = 0; i < matches.size(); i++) {
            MatchAnalysis<Score_> match = matches.get(i);

            summary.append("  ")
                    .append(i + 1)
                    .append(". Score: ")
                    .append(match.score())
                    .append(", Justification: ")
                    .append(match.justification())
                    .append(System.lineSeparator());
        }

        return summary.toString();
    }
}

