import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Objects;

public class ConstraintSummary {
    private static final int DEFAULT_MAX_MATCHES = 5;

    private final double overallScore;
    private final List<ConstraintMatch> matches;

    public ConstraintSummary(double overallScore, List<ConstraintMatch> matches) {
        this.overallScore = overallScore;
        this.matches = matches == null
                ? List.of()
                : List.copyOf(matches);
    }

    /**
     * Returns a summary displaying up to the default maximum number of matches.
     */
    public String summarize() {
        return summarize(DEFAULT_MAX_MATCHES);
    }

    /**
     * Returns a summary displaying up to maxMatches matches, sorted by score
     * in ascending order.
     */
    public String summarize(int maxMatches) {
        if (maxMatches < 0) {
            throw new IllegalArgumentException("maxMatches must not be negative");
        }

        List<ConstraintMatch> sortedMatches = new ArrayList<>(matches);
        sortedMatches.sort(Comparator.comparingDouble(ConstraintMatch::score));

        StringBuilder summary = new StringBuilder();
        summary.append(String.format(
                Locale.ROOT,
                "Overall score: %.2f%n",
                overallScore
        ));
        summary.append("Number of matches: ")
                .append(matches.size())
                .append('\n');

        int displayedCount = Math.min(maxMatches, sortedMatches.size());
        for (int i = 0; i < displayedCount; i++) {
            ConstraintMatch match = sortedMatches.get(i);
            summary.append(String.format(
                    Locale.ROOT,
                    "%d. Score: %.2f | Justification: %s%n",
                    i + 1,
                    match.score(),
                    match.justification()
            ));
        }

        if (sortedMatches.size() > maxMatches) {
            summary.append("...\n");
        }

        return summary.toString().trim();
    }

    public static final class ConstraintMatch {
        private final double score;
        private final String justification;

        public ConstraintMatch(double score, String justification) {
            this.score = score;
            this.justification = Objects.requireNonNullElse(justification, "");
        }

        public double score() {
            return score;
        }

        public String justification() {
            return justification;
        }
    }
}

