import java.beans.PropertyDescriptor;
import java.lang.reflect.Method;

import org.springframework.beans.BeanWrapper;
import org.springframework.beans.BeanWrapperImpl;

public final class BeanMergeUtils {

	private BeanMergeUtils() {
	}

	public static <I, T, S extends T> T mergeBeans(S source, T target, Class<I> sourceInterfaceClazz) {
		if (source == null || target == null || sourceInterfaceClazz == null) {
			return target;
		}

		BeanWrapper sourceWrapper = new BeanWrapperImpl(source);
		BeanWrapper targetWrapper = new BeanWrapperImpl(target);

		for (Method interfaceMethod : sourceInterfaceClazz.getMethods()) {
			if (!isGetter(interfaceMethod)) {
				continue;
			}

			PropertyDescriptor sourceDescriptor = findDescriptorByGetterName(
					sourceWrapper.getPropertyDescriptors(), interfaceMethod.getName());

			if (sourceDescriptor == null || sourceDescriptor.getReadMethod() == null) {
				continue;
			}

			String propertyName = sourceDescriptor.getName();

			if (!targetWrapper.isWritableProperty(propertyName)) {
				continue;
			}

			Object value = sourceWrapper.getPropertyValue(propertyName);
			if (value != null) {
				targetWrapper.setPropertyValue(propertyName, value);
			}
		}

		return target;
	}

	private static boolean isGetter(Method method) {
		if (method.getParameterCount() != 0 || method.getReturnType() == void.class
				|| method.isSynthetic() || method.isBridge()) {
			return false;
		}

		String methodName = method.getName();
		return (methodName.startsWith("get") && methodName.length() > 3)
				|| (methodName.startsWith("is") && methodName.length() > 2
						&& (method.getReturnType() == boolean.class
								|| method.getReturnType() == Boolean.class));
	}

	private static PropertyDescriptor findDescriptorByGetterName(PropertyDescriptor[] descriptors,
			String getterName) {
		for (PropertyDescriptor descriptor : descriptors) {
			Method readMethod = descriptor.getReadMethod();
