    }

    /**
     * Property names that must not be copied during bean merging.
     * Add application-specific property names to this set as needed.
     */
    private static final Set<String> BEAN_MERGE_FIELD_EXCISIONS =
            Collections.emptySet();

    public static <T, S extends T, I> T mergeBeans(
            S source,
            T target,
            Class<I> sourceInterfaceClazz,
            boolean overrideNonNullTargetValues) {

        Assert.notNull(source, "Source bean must not be null");
        Assert.notNull(target, "Target bean must not be null");
        Assert.notNull(sourceInterfaceClazz, "Source interface class must not be null");

        BeanWrapperImpl sourceWrapper = new BeanWrapperImpl(source);
        BeanWrapperImpl targetWrapper = new BeanWrapperImpl(target);

        PropertyDescriptor[] interfaceProperties =
                org.springframework.beans.BeanUtils
                        .getPropertyDescriptors(sourceInterfaceClazz);

        for (PropertyDescriptor propertyDescriptor : interfaceProperties) {
            String propertyName = propertyDescriptor.getName();

            if (BEAN_MERGE_FIELD_EXCISIONS.contains(propertyName)) {
                continue;
            }

            if (propertyDescriptor.getReadMethod() == null) {
                continue;
            }

            if (!sourceWrapper.isReadableProperty(propertyName)
                    || !targetWrapper.isWritableProperty(propertyName)) {
