            if (sourceValue == null) {
                continue;
            }

            if (!overrideNonNullTargetValues
                    && targetWrapper.isReadableProperty(propertyName)
                    && targetWrapper.getPropertyValue(propertyName) != null) {
                continue;
            }

            targetWrapper.setPropertyValue(propertyName, sourceValue);
        }

        return target;
    }
}

