public static List<Document> loadDocuments(Path directoryPath, DocumentParser documentParser) {
    if (!java.nio.file.Files.isDirectory(directoryPath)) {
        throw new IllegalArgumentException("Illegal directoryPath.");
    }

    List<Document> documents = new java.util.ArrayList<>();

    try (java.util.stream.Stream<Path> paths = java.nio.file.Files.list(directoryPath)) {
        paths.filter(java.nio.file.Files::isRegularFile)
             .map(documentParser::parse)
             .forEach(documents::add);
    } catch (java.io.IOException exception) {
        throw new java.io.UncheckedIOException(exception);
    }

    return documents;
}

